DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.pm_b1_stage_locked_cost(uuid)'::regprocedure) INTO d; d:=replace(d,'public.pm_b1_stage_locked_cost(_project uuid)','public.pm_b1_review_stage_locked_cost(_project uuid)'); d:=replace(d,'IF public.pm_project_b1_active() THEN','IF true THEN'); EXECUTE d; END $$; REVOKE ALL ON FUNCTION public.pm_b1_review_stage_locked_cost(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.pm_b1_review_stage_locked_cost(uuid) TO authenticated,service_role; COMMENT ON FUNCTION public.pm_b1_review_stage_locked_cost(uuid) IS 'Read-only own B1 Budget projection for OFF-gate review. Same project/PSA authorization and saved snapshots as active reader; never changes gate or identity.';